solution.minesweeper.zig:
const std = @import("std");
pub fn annotate(a: std.mem.Allocator, board: []const []const u8) ![][]u8 {
    for (board) |r| {
        if (r.len != board[0].len) return error.InvalidBoard;
    }
    const out = try a.alloc([]u8, board.len);
    var made: usize = 0;
    errdefer {
        for (out[0..made]) |row| a.free(row);
        a.free(out);
    }
    for (board, 0..) |row, y| {
        out[y] = try a.dupe(u8, row);
        made += 1;
        for (row, 0..) |c, x| {
            if (c == '*') continue;
            if (c != ' ') return error.InvalidBoard;
            var n: u8 = 0;
            for (0..3) |dy| {
                for (0..3) |dx| {
                    const yy = @as(isize, @intCast(y)) + @as(isize, @intCast(dy)) - 1;
                    const xx = @as(isize, @intCast(x)) + @as(isize, @intCast(dx)) - 1;
                    if (yy >= 0 and yy < board.len and xx >= 0 and xx < row.len and board[@intCast(yy)][@intCast(xx)] == '*') n += 1;
                }
            }
            out[y][x] = if (n == 0) ' ' else '0' + n;
        }
    }
    return out;
}

