tests.test_minesweeper.zig:
// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("minesweeper.zig");
test "all eight neighbors and boundaries" {
    const b = [_][]const u8{ "***", "* *", "***" };
    const r = try m.annotate(t.allocator, &b);
    defer {
        for (r) |row| t.allocator.free(row);
        t.allocator.free(r);
    }
    try t.expectEqualStrings("*8*", r[1]);
}
test "empty and sparse" {
    const b = [_][]const u8{ " * ", "   " };
    const r = try m.annotate(t.allocator, &b);
    defer {
        for (r) |row| t.allocator.free(row);
        t.allocator.free(r);
    }
    try t.expectEqualStrings("1*1", r[0]);
    try t.expectEqualStrings("111", r[1]);
    const e = try m.annotate(t.allocator, &.{});
    defer t.allocator.free(e);
    try t.expectEqual(@as(usize, 0), e.len);
}
test "python test_no_rows" {
    const out = try m.annotate(t.allocator, &.{});
    defer {
        for (out) |row| t.allocator.free(row);
        t.allocator.free(out);
    }
    const expected = [_][]const u8{};
    try t.expectEqual(expected.len, out.len);
    for (out, expected) |x, y| try t.expectEqualStrings(y, x);
}
